dashboard.definition:
{
    "title": "DLP and Cloud Native Security",
    "description": "Expose data-loss risk and cloud-native workload controls in one operational view.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h@h,now",
                "token": "time_tok"
            },
            "title": "Time Range",
            "type": "input.timerange"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1e293b",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "DLP and Cloud Native Security",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "markdown": "# DLP and Cloud Native Security\nExpose data\\-loss risk and cloud\\-native workload controls in one operational view\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#0f172a",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Data Loss Findings**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#7dd3fc",
                "fontSize": "custom",
                "customFontSize": 11,
                "markdown": "Security  •  Hybrid Mesh Firewalling"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#cbd5e1",
                "fontSize": "custom",
                "customFontSize": 12,
                "markdown": "Tracks Secure Access DLP findings by severity over time and moves the full finding breakdown into the drill\\-down modal\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#f1f5f9",
                "majorFontSize": 38,
                "majorValue": "> primary | seriesByName(\"WindowElevatedFindings\") | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.area",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#7dd3fc",
                    "#6ee7b7",
                    "#fdba74",
                    "#fda4af"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 3,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": true,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | seriesByName(\"ElevatedFindings\")"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Data%20Loss%20Findings&target=Secure%20Networking%20-%20Secure%20Access%20DLP%20Findings"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#0f172a",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 12
            }
        },
        "viz_card_02_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Workload Alert Pressure**"
            }
        },
        "viz_card_02_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#7dd3fc",
                "fontSize": "custom",
                "customFontSize": 11,
                "markdown": "Security  •  Microsegmentation"
            }
        },
        "viz_card_02_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#cbd5e1",
                "fontSize": "custom",
                "customFontSize": 12,
                "markdown": "Cisco Secure Workload \\(Tetration\\) alerts split by type \\(COMPLIANCE, TRAFFIC, SENSOR\\) and severity \\(critical, high, medium, and low\\), sourced from Cisco Secure Workload\\."
            }
        },
        "viz_card_02_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#f1f5f9",
                "majorFontSize": 38,
                "majorValue": "> primary | seriesByName(\"WindowTotal\") | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_card_02_trend": {
            "type": "splunk.bar",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "right",
                "seriesColors": [
                    "#7dd3fc",
                    "#6ee7b7",
                    "#fdba74",
                    "#fda4af"
                ],
                "showYMajorGridLines": true,
                "stackMode": "unstacked",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"Alert Category\")",
                "y": "> primary | seriesByName(\"Alerts\")"
            }
        },
        "viz_card_02_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Workload%20Alert%20Pressure&target=Secure%20Networking%20-%20Segmentation%20Secure%20Workload%20Alerts%20by%20Type"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_03_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#0f172a",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 12
            }
        },
        "viz_card_03_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Cloud Enforcement Rate**"
            }
        },
        "viz_card_03_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#7dd3fc",
                "fontSize": "custom",
                "customFontSize": 11,
                "markdown": "Security  •  Cloud Security"
            }
        },
        "viz_card_03_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#cbd5e1",
                "fontSize": "custom",
                "customFontSize": 12,
                "markdown": "Single\\-value deny rate across all Cisco Multicloud Defense security event subtypes \\(WAF, AV, DLP, URL/FQDN filter, L4 FW, L7 DoS, malicious source, SNI, TLS, DPI\\)\\. Excludes audit logs and gateway system logs\\."
            }
        },
        "viz_card_03_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
