    "dataSources": {
        "ds_story_01": {
            "name": "Secure Networking - Secure Access DLP Findings Trend",
            "options": {
                "ref": "secure_networking_secure_access_dlp_findings_trend",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            },
            "type": "ds.searchbase"
        },
        "ds_story_02": {
            "name": "Security - Microsegmentation - Secure Workload Alerts by Severity and Type",
            "options": {
                "ref": "security_microseg_tetration_alerts_by_severity_type",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            },
            "type": "ds.searchbase"
